function completeRoutine(id,d=today()){const r=S.routines.find(x=>x.id===id);if(!r||routineActivity(r,d))return;S.routineSkips=S.routineSkips.filter(x=>!(x.routineId===id&&x.date===d));const a={id:uid('a'),date:d,startTime:d===today()?localTime():(r.time||'00:00'),plannedTime:r.time||null,title:r.title,category:r.category||'personal',duration:Math.max(1,+r.duration||30),goalId:r.goalId||null,source:'routine',completed:true,routineId:r.id,rhythm:'routine',obligation:r.obligation||'important',planned:true,notes:''};S.activities.push(a);save();toast(r.title+' selesai · +'+activityXP(a)+' XP');render()}
